use std::{fs,path::PathBuf};
fn temp_project()->PathBuf{let root=std::env::temp_dir().join(format!("zuri-test-{}",std::process::id()));let _=fs::remove_dir_all(&root);fs::create_dir_all(&root).unwrap();fs::write(root.join("a.py"),"def helper(x):\n    return x\n\ndef main(value):\n    if value:\n        return helper(value)\n    return None\n").unwrap();root}
#[test]fn index_explain_trace_quiz_work_without_model(){let root=temp_project();let report=zuri_core::index_project(&root,true).unwrap();assert_eq!(report.python_files,1);assert!(report.stats.symbols>=2);let ex=zuri_core::explain(&root,"main").unwrap();assert!(ex.callees.iter().any(|c|c.name=="helper"));assert!(zuri_core::trace(&root,"main",2).unwrap().iter().any(|n|n.name=="helper"));assert!(!zuri_core::quiz(&root,"main").unwrap().is_empty());let _=fs::remove_dir_all(root);}
#[test]fn knowledge_pack_searches_offline(){let pack=zuri_core::KnowledgePack::ensure_builtin().unwrap();assert!(!pack.search("mutable default",5).unwrap().is_empty());}
